alter table public.jobs add column if not exists application_mode text not null default 'apply' check(application_mode in ('apply','register_interest'));alter table public.jobs add column if not exists opportunity_notice text;update public.jobs set application_mode='register_interest',opportunity_notice='Register your interest with TalentFlow. We are building a candidate pool for this opportunity before a client recruitment agreement is confirmed. Registration does not mean you have been submitted to, endorsed by, or accepted by Kinetic Energy Solutions Ltd.' where client_id=(select id from public.clients where company_name='Kinetic Energy Solutions Ltd' limit 1) and status='published';
